import {knowledgeCategories,saveKnowledge,activeKnowledge} from './knowledge.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountKnowledge(root,{entries,onSave,readOnly=false,label='Review demo — changes are saved in this browser only.'}){
 let query='',category='All categories',status='All statuses';let editor;
 function draw(){const filtered=entries.filter(e=>(category==='All categories'||e.category===category)&&(status==='All statuses'?e.status!=='archived':e.status===status)&&(e.question+' '+e.answer).toLowerCase().includes(query.toLowerCase()));
 root.innerHTML=`<div class="kb-heading"><div><h2>Teach Charlotte your dealership’s answers.</h2><p class="muted">Your policies, in your words. Only active, unexpired answers are available to Charlotte.</p></div><button class="primary" id="kb-add" ${readOnly?'disabled':''}>+ Add Q&A</button></div><div class="kb-summary"><span class="badge">${activeKnowledge(entries).length} active</span><span class="badge warn">${entries.filter(e=>e.status==='draft').length} need review</span><span class="muted">${esc(label)}</span></div><div class="toolbar"><input class="search" id="kb-search" aria-label="Search knowledge base" placeholder="Search questions and answers…" value="${esc(query)}"><select id="kb-category" aria-label="Knowledge category">${['All categories',...knowledgeCategories].map(c=>`<option ${c===category?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="kb-status" aria-label="Knowledge status">${['All statuses','active','draft','archived'].map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select></div><div id="kb-notice" role="status"></div><div class="kb-list">${filtered.map(e=>`<article class="panel kb-card"><div class="kb-card-top"><span class="muted">${esc(e.category)}</span><span class="badge ${e.status==='active'?'':e.status==='draft'?'warn':'red'}">${e.expiresAt&&e.expiresAt<=Date.now()?'Expired':esc(e.status==='active'?'Active':e.status==='draft'?'Needs review':'Archived')}</span></div><h3>${esc(e.question)}</h3><p class="kb-answer">${esc(e.answer||'Answer not yet supplied')}</p>${e.reviewReason?`<div class="kb-review">${esc(e.reviewReason)}</div>`:''}<div class="kb-footer"><small>${esc(e.source)}<br>Updated ${esc(new Date(e.updatedAt).toLocaleDateString())} · ${esc(e.updatedBy)} · revision ${e.revision}</small><button data-kb-edit="${e.id}" ${readOnly?'disabled':''}>${e.status==='draft'?'Review & edit':'Edit'}</button></div></article>`).join('')||'<div class="panel empty">No answers match these filters.</div>'}</div><dialog id="kb-editor"><form id="kb-form"><h2 id="kb-editor-title">Add an answer</h2><label>Question<input id="kb-question" required minlength="5" maxlength="300"></label><label>Answer<textarea id="kb-answer" maxlength="4000" rows="5"></textarea></label><label>Category<select id="kb-edit-category">${knowledgeCategories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>Status<select id="kb-edit-status"><option value="draft">Needs review</option><option value="active">Active for Charlotte</option><option value="archived">Archived — kept in history</option></select></label><label>Review again after (optional)<input type="date" id="kb-expiry"></label><div id="kb-review-note" class="muted"></div><label class="check"><input type="checkbox" id="kb-confirm"> I have verified this dealership policy. It does not authorize financing promises or override live inventory.</label><details id="kb-history"><summary>Original import & revision history</summary><div id="kb-history-body"></div></details><p id="kb-editor-error" role="alert"></p><div class="actions"><button type="button" id="kb-close">Cancel</button><button class="primary" type="submit">Save answer</button></div></form></dialog>`;
 const search=root.querySelector('#kb-search');search.oninput=()=>{const pos=search.selectionStart;query=search.value;draw();const next=root.querySelector('#kb-search');next.focus();next.setSelectionRange(pos,pos);};root.querySelector('#kb-category').onchange=e=>{category=e.target.value;draw();};root.querySelector('#kb-status').onchange=e=>{status=e.target.value;draw();};root.querySelector('#kb-add').onclick=()=>open(null);root.querySelectorAll('[data-kb-edit]').forEach(b=>b.onclick=()=>open(entries.find(e=>e.id===b.dataset.kbEdit)));root.querySelector('#kb-close').onclick=()=>root.querySelector('#kb-editor').close();root.querySelector('#kb-form').onsubmit=submit;
 }
 function open(row){editor=row?structuredClone(row):null;const get=id=>root.querySelector('#'+id);get('kb-editor-title').textContent=row?'Review dealership answer':'Add dealership answer';get('kb-question').value=row?.question||'';get('kb-answer').value=row?.answer||'';get('kb-edit-category').value=row?.category||'General';get('kb-edit-status').value=row?.status||'draft';get('kb-expiry').value=row?.expiresAt?new Date(row.expiresAt).toISOString().slice(0,10):'';get('kb-confirm').checked=false;get('kb-review-note').textContent=row?.reviewReason||'Use current dealership facts. Unknown answers should stay in review.';get('kb-editor-error').textContent='';get('kb-history-body').innerHTML=`<p>${esc(row?.originalAnswer||'No imported original')}</p>`+(row?.history||[]).slice().reverse().map(h=>`<p><strong>Revision ${h.revision} · ${esc(h.status)}</strong><br>${esc(h.answer)}</p>`).join('');get('kb-editor').showModal();}
 async function submit(e){e.preventDefault();const get=id=>root.querySelector('#'+id);try{const input={id:editor?.id,revision:editor?.revision,question:get('kb-question').value,answer:get('kb-answer').value,category:get('kb-edit-category').value,status:get('kb-edit-status').value,expiresAt:get('kb-expiry').value?get('kb-expiry').value+'T23:59:59Z':null,reviewConfirmed:get('kb-confirm').checked};const updated=structuredClone(entries);saveKnowledge(updated,input);const result=await onSave(input,updated);entries=result||updated;draw();root.querySelector('#kb-notice').textContent='Answer saved. '+(label.includes('browser')?'Demo changes stay on this browser.':'Charlotte uses active answers on her next reply.');}catch(err){get('kb-editor-error').textContent=err.message;}}
 draw();
}
